  if (/docker/.test(value)) categories.push("Docker");
  if (/seed|demo/.test(value)) categories.push("seed");
  if (/migrat|schema|db:|preflight|verify/.test(value)) categories.push("database");
  if (/test|vitest|playwright|e2e|integration/.test(value)) categories.push(value.includes("e2e") || value.includes("playwright") ? "E2E" : "integration");
