const typeSafety = { explicitAny: [], asAny: [], tsIgnore: [], tsExpectError: [], eslintDisable: [], nonNullSensitive: [], unvalidatedJson: [] };
for (const file of sourceFiles.filter((entry) => /^(app|lib|components)\//.test(entry) && /\.(ts|tsx)$/.test(entry))) {
  for (const [index, line] of lines(file).entries()) {
    const record = { file, line: index + 1, source: line.trim().slice(0, 240) };
    if (/(?:[:<,]\s*any\b|=\s*any\b|\bany\[\]|Array<any>|Record<[^>]*,\s*any>)/.test(line) && !/^\s*(?:\/\/|\*)/.test(line)) typeSafety.explicitAny.push({ ...record, classification: /eslint-disable.*no-explicit-any|type\s+\w+\s*=\s*any/.test(line) ? "intentional/deferred-but-unsafe" : "needs-review" });
    if (/\bas\s+any\b/.test(line)) typeSafety.asAny.push({ ...record, classification: "unsafe-cast-needs-review" });
    if (/@ts-ignore/.test(line)) typeSafety.tsIgnore.push({ ...record, classification: "suppressed-type-error" });
    if (/@ts-expect-error/.test(line)) typeSafety.tsExpectError.push({ ...record, classification: "expected-type-error-needs-review" });
    if (/eslint-disable/.test(line)) typeSafety.eslintDisable.push({ ...record, classification: "lint-suppression-needs-review" });
    if (/!\.|!\[|\w+!\b/.test(line) && /payment|refund|withdraw|promot|driver|order|claim|media|privacy/i.test(`${file} ${line}`)) typeSafety.nonNullSensitive.push({ ...record, classification: "sensitive-flow-non-null-assertion" });
    if (/\.json\(\)|JSON\.parse\(/.test(line) && !/safeParse|parse\(/.test(line)) typeSafety.unvalidatedJson.push({ ...record, classification: "raw-json-boundary-needs-schema-review" });
  }
}

